namespace Acme.Core.Data;

/// <summary>
/// The base for every persisted entity. The key is generated by the EF Core provider (never in entity code),
/// and the audit fields are filled by <see cref="AuditSaveChangesInterceptor"/>.
/// </summary>
public abstract class BaseEntity
{
    public Guid Id { get; protected set; }

    public DateTime CreatedOn { get; private set; }

    public string? CreatedBy { get; private set; }

    public DateTime? UpdatedOn { get; private set; }

    public string? UpdatedBy { get; private set; }

    internal void SetCreated(DateTime utcNow, string? by)
    {
        CreatedOn = utcNow;
        CreatedBy = by;
    }

    internal void SetUpdated(DateTime utcNow, string? by)
    {
        UpdatedOn = utcNow;
        UpdatedBy = by;
    }
}

/// <summary>An aggregate root: gets optimistic concurrency (a provider row version, exposed as an ETag).</summary>
public interface IAggregateRoot;

/// <summary>Soft-deletable entities are hidden by a global query filter.</summary>
public interface ISoftDeletable
{
    bool IsDeleted { get; }

    DateTime? DeletedOn { get; }

    void MarkDeleted(DateTime utcNow);
}
